 LEFT JOIN Pubs_Info_V4.dbo.Attachment a ON a.PIN_ID=pin.PIN_ID
 JOIN Pubs_Info_V4.dbo.Public_info_News_Prodc p ON p.News_ID=pin.PIN_ID;
